(function (global) {
  'use strict';
  var pack = {"manifest":{"id":"drilling-trajectory","sceneId":"d3","title":"井眼轨迹智能控制","status":"ready","version":"1.0.0","updated":"2026-10-23","methods":["opt"],"tabs":{"background":{"label":"专业背景","lede":"定向钻井需要根据随钻测点调整后续井段，使井眼接近目标并限制过度弯曲。这个实验将地层响应辨识与滚动约束搜索连接起来，比较当前状态下控制轨迹和零指令轨迹的终点距离。","judge":[{"label":"数据来源","value":"教学合成","desc":"固定种子，可导出核查"},{"label":"方法类型","value":"响应辨识与滚动优化","desc":"纯前端轻量计算"},{"label":"输出用途","value":"教学比较","desc":"不连接设备与现场系统"},{"label":"评价边界","value":"合成任务","desc":"不声称真实工程收益"}],"sections":[{"no":1,"en":"BUSINESS","title":"定向井轨迹与曲率约束","html":"<p>井斜表示井眼相对铅垂方向的夹角；测深沿井眼累积，垂深沿竖直方向量取。轨迹弯曲过急会影响工具通过并增加摩阻。固定方位的二维模型可用相邻 30 m 段的井斜差表示曲率，真实三维狗腿度还要计入方位变化。</p><figure class=\"figure\"><div style=\"overflow-x:auto\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 118\" role=\"img\" aria-label=\"定向井轨迹与曲率约束\" style=\"width:100%;min-width:560px;max-width:640px;display:block;margin:auto\"><rect x=\"18\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"105\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">随钻测点</text><text x=\"105\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">水平 / 垂深 / 井斜</text><path d=\"M194 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"208\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"295\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">工具与地层响应</text><text x=\"295\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">动作改变后续井斜</text><path d=\"M384 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"398\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"485\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">靶点与曲率</text><text x=\"485\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">位置目标 + 操作约束</text></svg></div><figcaption class=\"figcap\">业务关系示意，不是测量结果。窄屏可在图内横向滚动。</figcaption></figure>"},{"no":2,"en":"METHOD","title":"响应辨识与滚动优化","html":"<p>用独立合成校准数据拟合指令到井斜增量的线性响应。在每个测点枚举未来三段指令，排除预测井斜及曲率超限序列，对靶点距离、末端井斜和动作平滑性加权评分，只执行最优序列第一步。新测点反馈后重新规划。这是二维有限动作滚动优化，不是三维自动导向软件。</p>"},{"no":3,"en":"DATA","title":"数据准备与评价切分","html":"<p>24 条合成校准记录用于估计动作增益和自然漂移；控制模拟共 20 段，每段 30 m。靶点固定垂深 500 m，水平位置可调。未建模扰动只施加到模拟井眼，不偷偷传给规划模型。实际应用需要 MWD 测点、工具性能、地层响应和井眼约束，并对测量时延建模。</p>"},{"no":4,"en":"LIMITS","title":"模型适用范围与工程约束","html":"<p>轨迹采用测段平均井斜积分，不实现完整最小曲率法、三维方位与工具面控制、避碰或摩阻计算。预测可行不保证实际可行：扰动可能使真实模拟曲率超限，页面单独报告。无可行序列时停止模拟，不能强行输出动作。固定测深终点距离不是中靶率或最优性证明。</p><p>专业资料与方法来源：</p><ul><li><a href=\"https://www.slb.com/resource-library/oilfield-review/defining-series/defining-directional-drilling\" target=\"_blank\" rel=\"noopener noreferrer\">SLB：Directional Drilling Practices</a>：支持定向钻井、地层响应与工具能力约束背景，不支持本例简化模型与权重。</li><li><a href=\"https://glossary.slb.com/terms/d/dogleg\" target=\"_blank\" rel=\"noopener noreferrer\">SLB：dogleg</a>：支持狗腿及曲率变化的工程影响；本例固定方位二维曲率是简化情况。</li></ul>"}]},"workflow":{"label":"案例流程","title":"响应辨识与滚动优化","lead":["定向钻井需要根据随钻测点调整后续井段，使井眼接近目标并限制过度弯曲。这个实验将地层响应辨识与滚动约束搜索连接起来，比较当前状态下控制轨迹和零指令轨迹的终点距离。"],"stats":[["数据","固定种子合成"],["运行方式","浏览器本地"],["工程用途","方法教学"]],"steps":[{"name":"测段响应辨识","role":"数据","do":"24 条独立记录回归增益与自然漂移。","effect":"建立可核对的轻量预测模型。","trap":"校准模型不随目标值改变，也不读取未来扰动。"},{"name":"有限动作序列搜索","role":"算法","do":"枚举三段共 729 个指令序列并预测测段终点。","effect":"比较未来响应而不是只纠正当前误差。","trap":"短预测窗不保证全局最优。"},{"name":"约束筛选与执行","role":"控制","do":"剔除预测曲率和井斜越界序列，只执行首个动作。","effect":"限制教学模型中的急弯并滚动纠偏。","trap":"实际扰动可能使曲率超出预测上限。"},{"name":"轨迹对比与复核","role":"评价","do":"按相同初态和扰动运行零指令基线，核对终点距靶与实际曲率。","effect":"同时显示跟踪效果与约束偏差。","trap":"基线没有控制动作，不代表工程师的最佳手动策略。"}],"metrics":{"title":"计算指标与评价边界","html":"<figure class=\"figure\"><div style=\"overflow-x:auto\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 118\" role=\"img\" aria-label=\"案例计算流程\" style=\"width:100%;min-width:560px;max-width:640px;display:block;margin:auto\"><rect x=\"18\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"105\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">响应校准</text><text x=\"105\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">24 条独立合成记录</text><path d=\"M194 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"208\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"295\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">三段约束搜索</text><text x=\"295\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">729 序列 / 首步执行</text><path d=\"M384 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"398\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"485\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">新测点反馈</text><text x=\"485\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">终点偏差 / 实际曲率</text></svg></div><figcaption class=\"figcap\">输入、计算与评价之间的关系示意；结果由演示实际计算。</figcaption></figure><p>终点距靶=√((x末−x靶)²+(z末−500)²)，单位 m。实际曲率=相邻段井斜差绝对值，单位 °/30m。零指令基线在同样扰动下计算；两者均固定最多 600 m 测深，终点距离不保证沿途是否穿靶。模型代价含人为权重，不代表真实经济损失。</p>"},"fails":[{"name":"数据分布变化","why":"轨迹采用测段平均井斜积分，不实现完整最小曲率法、三维方位与工具面控制、避碰或摩阻计算。预测可行不保证实际可行：扰动可能使真实模拟曲率超限，页面单独报告。无可行序列时停止模拟，不能强行输出动作。固定测深终点距离不是中靶率或最优性证明。"},{"name":"合成结果误用","why":"所有数据、参数范围、阈值和响应系数均为教学合成设定；资料只支持业务定义和方法动机，不支持本例数值与现场收益。"}]},"demo":{"mode":"page","html":"demo/index.html","js":"demo/demo.js","label":"案例演示","height":1200,"intro":"定向钻井需要根据随钻测点调整后续井段，使井眼接近目标并限制过度弯曲。这个实验将地层响应辨识与滚动约束搜索连接起来，比较当前状态下控制轨迹和零指令轨迹的终点距离。"}}},"files":[{"name":"demo/demo.css","size":3674,"enc":"text","data":":root{font:16px/1.8 -apple-system,BlinkMacSystemFont,\"Segoe UI\",\"Microsoft YaHei\",sans-serif;color:#242b2e;background:#fbfaf6;--jade:#2f7d6b;--line:#ddd7c8;--muted:#56646b}\n*{box-sizing:border-box}body{margin:0}main{max-width:1200px;margin:auto;padding:24px}h1,h2,h3,p{margin:0}h1{font-size:clamp(24px,3vw,32px);line-height:1.4;margin:12px 0}h2{font-size:21px;line-height:1.5;margin-bottom:12px}h3{font-size:18px;margin:20px 0 10px}p{color:var(--muted)}header{margin-bottom:24px}header p{max-width:80ch}.badge{font-size:14px;color:#235f51;background:#e6f1ec;border-radius:4px;padding:5px 9px}.experiment{display:grid;grid-template-columns:285px minmax(0,1fr);border:1px solid var(--line);border-radius:12px;overflow:hidden;background:white}aside{background:#f3f5f0;padding:22px;border-right:1px solid var(--line)}.field{display:block;margin:18px 0}.field>span{display:flex;flex-wrap:wrap;justify-content:space-between;gap:6px;font-weight:600}.field output{color:var(--jade);font-variant-numeric:tabular-nums}input,select,button{font:inherit}input[type=range]{width:100%;accent-color:var(--jade);margin:14px 0;cursor:pointer}select{display:block;width:100%;min-height:44px;margin:8px 0;border:1px solid var(--line);border-radius:5px;background:white;padding:7px}small,.hint,.boundary{font-size:14px;color:var(--muted);line-height:1.75}.boundary{margin-top:18px;border-top:1px solid var(--line);padding-top:12px}button{min-height:44px;padding:8px 14px;color:white;background:var(--jade);border:1px solid var(--jade);border-radius:6px;cursor:pointer}button.quiet{background:white;color:var(--jade);border-color:var(--line)}button[hidden]{display:none}button:hover{filter:brightness(.95)}:focus-visible{outline:3px solid #41699b;outline-offset:3px}.results{padding:24px;min-width:0}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.metrics>div{padding:12px 14px;background:#f5f7f4;border:1px solid #e3e8e4;border-radius:6px}.metrics span{display:block;font-size:14px;color:var(--muted)}.metrics strong{display:block;font-size:23px;font-weight:600;line-height:1.5;color:#235f51;font-variant-numeric:tabular-nums}#status{padding:14px 0;font-size:15px}#apply{margin-bottom:16px}.chart{border-top:1px solid var(--line);padding-top:22px;margin-top:22px}.chart p{font-size:15px;line-height:1.8}.chart-scroll,.table-scroll{overflow:auto;overscroll-behavior-x:contain;padding-bottom:6px}svg{width:100%;max-width:700px;height:auto;display:block;margin:12px auto 4px}svg text{font:16px -apple-system,BlinkMacSystemFont,\"Microsoft YaHei\",sans-serif;fill:var(--muted)}.legend{display:flex;gap:10px 18px;flex-wrap:wrap;font-size:14px}.legend span{display:flex;align-items:center;gap:7px}.legend i{display:block;width:14px;height:4px}.details{margin-top:28px}.details>p{max-width:95ch}table{width:100%;border-collapse:collapse;font-size:15px;font-variant-numeric:tabular-nums}th,td{text-align:left;padding:9px 12px;border-bottom:1px solid var(--line);white-space:nowrap}th{background:#f3f5f0;font-weight:600}#download{margin-top:18px}footer{font-size:14px;color:var(--muted);padding:18px 0;margin-top:26px;border-top:1px solid var(--line)}\n@media(max-width:1000px){.experiment{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid var(--line)}#controls{display:grid;grid-template-columns:1fr 1fr;gap:0 24px}.field{margin:10px 0}}\n@media(max-width:600px){main{padding:12px}.results,aside{padding:16px}#controls{grid-template-columns:1fr}.metrics{gap:8px}.metrics strong{font-size:20px}.chart-scroll svg{width:640px;max-width:none}.badge{display:inline-block;font-size:13px}}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\n"},{"name":"demo/demo.js","size":3227,"enc":"text","data":"(function(){\n  'use strict';const M=TrajectoryModel,F=CaseUI.f;\n  CaseUI.mount({id:'drilling-trajectory',title:'井眼轨迹智能控制',intro:'在固定方位的二维井段内，辨识简化工具响应，再滚动搜索未来三个测段的造斜指令。目标位置、曲率限制与未建模扰动共同影响最终偏差。',boundary:'仅表示固定方位二维轨迹，不实现三维工具面控制、地质导向、避碰、摩阻或井控。实际响应超限会明确显示。',controls:[{id:'target',label:'靶点水平位移',min:100,max:380,step:10,value:250,unit:'m'},{id:'angle',label:'初始井斜角',min:5,max:65,step:1,value:20,unit:'°'},{id:'limit',label:'预测曲率上限',min:.5,max:3,step:.25,value:2,unit:'°/30m'},{id:'disturbance',label:'未建模造斜扰动',min:-.6,max:.6,step:.1,value:.2,unit:'°/30m'}],method:'24 条独立合成校准记录回归 Δ井斜=增益×指令+自然漂移，随后冻结辨识结果。每个 30 m 测段枚举 9³=729 个三步指令序列，剔除预测井斜或曲率越界序列，按靶点距离、末端井斜与动作平滑性组成的教学代价选优，只执行第一步，再用新状态重新规划。总计 20 段、600 m 测深。积分采用平均井斜近似，不是完整最小曲率法。',\n    compute:s=>{const a=M.simulate(s,true),b=M.simulate(s,false),m=a.model,within=a.maxDls<=s.limit+1e-9;\n      return {metrics:[['控制轨迹终点距靶',F(a.miss,1)+' m'],['零指令终点距靶',F(b.miss,1)+' m'],['实际最大曲率',F(a.maxDls)+' °/30m'],['完成测深',(a.rows.length-1)*30+' m']],summary:`辨识增益 ${F(m.gain,3)}、漂移 ${F(m.drift,3)} °/30m。${a.infeasible?'出现无可行序列，已停止模拟。':within?'本次实际曲率处于所设教学上限内。':'未建模扰动导致实际曲率超过预测约束，须重新辨识或扩大约束余量。'} 距靶以固定 600 m 测深终点计算，不保证轨迹穿过靶点。`,\n        plots:[{title:'二维井眼轨迹与靶点',xLabel:'水平位移 m',yLabel:'向下垂深的负值 m',yRange:[-650,20],note:'为使图上向下对应井深增加，纵轴显示 −TVD；靶点为垂深 500 m。蓝线是同样扰动下的零指令基线。',series:[{name:'滚动优化轨迹',points:a.rows.map(r=>[r.x,-r.z])},{name:'零指令基线',points:b.rows.map(r=>[r.x,-r.z])},{name:'靶点',dots:true,points:[[s.target,-500]]}]},\n        {title:'测段曲率与操作指令',xLabel:'测深 m',yLabel:'曲率 °/30m',yRange:[0,4],hlines:[s.limit],note:'每个点是相邻测段井斜差的绝对值，固定方位下等于本例曲率；红虚线为教学上限。动作指令见数据表。',series:[{name:'实际曲率',points:a.rows.map((r,i)=>[i*30,r.dls])},{name:'零指令曲率',points:b.rows.map((r,i)=>[i*30,r.dls])}]}],\n        table:{title:'控制轨迹测段记录',headers:['测深 m','水平 m','垂深 m','井斜 °','归一化指令','曲率 °/30m'],rows:a.rows.map((r,i)=>[i*30,F(r.x,1),F(r.z,1),F(r.angle),F(r.u),F(r.dls)]),note:'指令 −1 到 1 表示教学造斜强度，不是可直接下发的工具面角。终点距离是欧氏距离，不表示真实中靶率。'},records:a.rows.map((r,i)=>({measured_depth_m:i*30,...r}))};}\n  });\n})();\n"},{"name":"demo/index.html","size":422,"enc":"text","data":"<!doctype html>\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>井眼轨迹智能控制</title><link rel=\"stylesheet\" href=\"demo.css\"></head><body><main id=\"app\"></main><noscript>需要启用 JavaScript 才能运行本地计算。</noscript><script src=\"model.js\"></script><script src=\"ui.js\"></script><script src=\"demo.js\"></script></body></html>"},{"name":"demo/model.js","size":2341,"enc":"text","data":"(function(g){\n  'use strict';\n  const rad=Math.PI/180;\n  // Constant plane, 30 m step; midpoint integration is a teaching approximation.\n  function advance(p,u,drift,gain){const angle=p.angle+gain*u+drift;return {x:p.x+30*Math.sin((p.angle+angle)*.5*rad),z:p.z+30*Math.cos((p.angle+angle)*.5*rad),angle,u,dls:Math.abs(angle-p.angle)};}\n  function identify(){\n    const rows=Array.from({length:24},(_,i)=>{const u=(i%7-3)/3;return {u,delta:2.4*u+.18+.05*Math.sin(i*1.7)};});\n    const mx=rows.reduce((s,r)=>s+r.u,0)/rows.length,my=rows.reduce((s,r)=>s+r.delta,0)/rows.length;\n    const gain=rows.reduce((s,r)=>s+(r.u-mx)*(r.delta-my),0)/rows.reduce((s,r)=>s+(r.u-mx)**2,0);\n    return {gain,drift:my-gain*mx,rows};\n  }\n  function search(p,goal,state,model){\n    const actions=[-1,-.75,-.5,-.25,0,.25,.5,.75,1];let best=null,count=0;\n    // Three-step receding horizon, enumerate 729 sequences; only first is applied.\n    for(const a of actions)for(const b of actions)for(const c of actions){\n      let q=p,cost=0,valid=true;const seq=[a,b,c];\n      for(let k=0;k<3;k++){\n        const n=advance(q,seq[k],model.drift,model.gain);\n        if(n.dls>state.limit+1e-9||n.angle<0||n.angle>85){valid=false;break;}\n        cost+=.35*seq[k]**2+.6*(seq[k]-(q.u||0))**2;q=n;\n      }\n      if(!valid)continue;count++;\n      const desired=Math.atan2(goal.x-q.x,Math.max(1,goal.z-q.z))/rad;\n      cost+=(q.x-goal.x)**2/900+(q.z-goal.z)**2/900+.04*(q.angle-desired)**2;\n      if(!best||cost<best.cost)best={u:a,cost,sequence:seq,endpoint:q};\n    }\n    return {best,count};\n  }\n  function simulate(s,controlled){\n    const model=identify(),start={x:0,z:0,angle:s.angle,u:0,dls:0};let p=start;const rows=[p];let infeasible=false;\n    for(let i=0;i<20;i++){\n      let u=0;\n      if(controlled){const pick=search(p,{x:s.target,z:500},s,model);if(!pick.best){infeasible=true;break;}u=pick.best.u;}\n      // Freeze identified model; plant has a user-controlled unmodelled disturbance.\n      p=advance(p,u,model.drift+s.disturbance,model.gain);\n      rows.push(p);\n    }\n    return {rows,infeasible,miss:Math.hypot(p.x-s.target,p.z-500),maxDls:Math.max(...rows.map(r=>r.dls)),model};\n  }\n  const api={advance,identify,search,simulate};if(typeof module!=='undefined')module.exports=api;else g.TrajectoryModel=api;\n})(typeof window!=='undefined'?window:globalThis);\n"},{"name":"demo/ui.js","size":6241,"enc":"text","data":"(function(g){\n  'use strict';\n  const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n  const f=(v,n=2)=>v===null||!Number.isFinite(v)?'不可定义':v.toFixed(n);\n  function plot(p,index){\n    const W=700,H=340,L=85,R=24,T=38,B=64;\n    const all=p.series.flatMap(s=>s.points).filter(a=>a.every(Number.isFinite));\n    const extent=(k)=>{const v=all.map(a=>a[k]);let a=Math.min(...v),b=Math.max(...v);if(a===b){a-=1;b+=1;}return [a,b];};\n    const xr=p.xRange||extent(0),yr=p.yRange||extent(1),x=v=>L+(v-xr[0])/(xr[1]-xr[0])*(W-L-R),y=v=>H-B-(v-yr[0])/(yr[1]-yr[0])*(H-T-B);\n    let svg=`<defs><clipPath id=\"clip${index}\"><rect x=\"${L}\" y=\"${T}\" width=\"${W-L-R}\" height=\"${H-T-B}\"/></clipPath></defs>`;\n    for(let i=0;i<=4;i++){const xv=xr[0]+(xr[1]-xr[0])*i/4,yv=yr[0]+(yr[1]-yr[0])*i/4;svg+=`<path d=\"M${L} ${y(yv)}H${W-R}\" stroke=\"#e3e8e4\"/><text x=\"${L-10}\" y=\"${y(yv)+5}\" text-anchor=\"end\">${f(yv,p.decimals??1)}</text><text x=\"${x(xv)}\" y=\"${H-B+27}\" text-anchor=\"middle\">${f(xv,p.xDecimals??0)}</text>`;}\n    svg+=`<text x=\"${L}\" y=\"22\">${esc(p.yLabel)}</text><text x=\"${(L+W-R)/2}\" y=\"${H-8}\" text-anchor=\"middle\">${esc(p.xLabel)}</text><g clip-path=\"url(#clip${index})\">`;\n    (p.bands||[]).forEach(b=>{svg+=`<rect x=\"${x(b.from)}\" y=\"${T}\" width=\"${x(b.to)-x(b.from)}\" height=\"${H-T-B}\" fill=\"#f8ecdf\"/>`;});\n    (p.hlines||[]).forEach(v=>svg+=`<path d=\"M${L} ${y(v)}H${W-R}\" stroke=\"#a34138\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>`);\n    (p.vlines||[]).forEach(v=>svg+=`<path d=\"M${x(v)} ${T}V${H-B}\" stroke=\"#8e5229\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>`);\n    const colors=['#2f7d6b','#41699b','#b26a39','#7e5a8d'];\n    p.series.forEach((s,i)=>{const pts=s.points.filter(a=>a.every(Number.isFinite)),color=s.color||colors[i%4];if(s.dots)pts.forEach(a=>svg+=`<circle cx=\"${x(a[0])}\" cy=\"${y(a[1])}\" r=\"3.5\" fill=\"${color}\" opacity=\".65\"><title>${esc(s.name)}：${f(a[0])}, ${f(a[1])}</title></circle>`);else svg+=`<path d=\"${pts.map((a,j)=>(j?'L':'M')+x(a[0])+','+y(a[1])).join(' ')}\" fill=\"none\" stroke=\"${color}\" stroke-width=\"2.5\" ${s.dashed?'stroke-dasharray=\"7 5\"':''}/>`;});svg+='</g>';\n    return `<article class=\"chart\"><h2>${esc(p.title)}</h2><p>${esc(p.note)}</p><div class=\"chart-scroll\" role=\"region\" tabindex=\"0\" aria-label=\"${esc(p.title)}，窄屏可横向滚动\"><svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"${esc(p.title+'；'+p.yLabel+'；'+p.xLabel)}\">${svg}</svg></div><div class=\"legend\">${p.series.map((s,i)=>`<span><i style=\"background:${s.color||colors[i%4]}\"></i>${esc(s.name)}</span>`).join('')}</div></article>`;\n  }\n  function mount(c){\n    const root=document.getElementById('app');let result;\n    root.innerHTML=`<header><span class=\"badge\">教学合成数据 · 本地计算 · 固定种子</span><h1>${esc(c.title)}</h1><p>${esc(c.intro)}</p></header><section class=\"experiment\"><aside><h2>实验设置</h2><form id=\"controls\">${c.controls.map(a=>`<label class=\"field\" for=\"${a.id}\"><span>${esc(a.label)} <output id=\"${a.id}-value\"></output></span>${a.options?`<select id=\"${a.id}\">${a.options.map(o=>`<option value=\"${esc(o[0])}\">${esc(o[1])}</option>`).join('')}</select>`:`<input id=\"${a.id}\" type=\"range\" min=\"${a.min}\" max=\"${a.max}\" step=\"${a.step}\" value=\"${a.value}\">`}<small>${esc(a.hint||'')}</small></label>`).join('')}</form><button id=\"reset\" class=\"quiet\" type=\"button\">恢复初始设置</button><p class=\"boundary\">${esc(c.boundary)}</p></aside><div class=\"results\"><h2>计算结果</h2><div id=\"metrics\" class=\"metrics\"></div><p id=\"status\" role=\"status\"></p><button id=\"apply\" type=\"button\" hidden>应用推荐参数</button><div id=\"plots\"></div></div></section><section class=\"details\"><h2>方法与评价边界</h2><p>${esc(c.method)}</p><div id=\"table\"></div><button id=\"download\" class=\"quiet\" type=\"button\">导出当前实验 CSV</button></section><footer>所有范围、阈值、响应系数和目标均为教学设置；合成评价不能证明现场效果。演示不连接设备。图表可通过下方数据表及 CSV 核对。</footer>`;\n    const read=()=>Object.fromEntries(c.controls.map(a=>[a.id,a.options?document.getElementById(a.id).value:+document.getElementById(a.id).value]));\n    function render(){const s=read();c.controls.forEach(a=>document.getElementById(a.id+'-value').textContent=a.options?'':s[a.id]+(a.unit?' '+a.unit:''));result=c.compute(s);document.getElementById('metrics').innerHTML=result.metrics.map(a=>`<div><span>${esc(a[0])}</span><strong>${esc(a[1])}</strong></div>`).join('');document.getElementById('status').textContent=result.summary;document.getElementById('plots').innerHTML=result.plots.map(plot).join('');const table=result.table;document.getElementById('table').innerHTML=`<h3>${esc(table.title)}</h3><div class=\"table-scroll\"><table><thead><tr>${table.headers.map(v=>`<th scope=\"col\">${esc(v)}</th>`).join('')}</tr></thead><tbody>${table.rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class=\"hint\">${esc(table.note||'')}</p>`;document.getElementById('apply').hidden=!result.apply;}\n    document.getElementById('controls').addEventListener('submit',e=>e.preventDefault());\n    c.controls.forEach(a=>document.getElementById(a.id).addEventListener(a.options?'change':'input',render));\n    document.getElementById('reset').onclick=()=>{c.controls.forEach(a=>document.getElementById(a.id).value=a.value);render();};\n    document.getElementById('apply').onclick=()=>{if(result.apply){Object.entries(result.apply).forEach(([k,v])=>document.getElementById(k).value=v);render();}};\n    document.getElementById('download').onclick=()=>{const rows=result.records;if(!rows.length)return;const keys=Object.keys(rows[0]),cell=v=>'\"'+String(v??'').replace(/\"/g,'\"\"')+'\"';const csv='\\uFEFF'+[keys,...rows.map(r=>keys.map(k=>r[k]))].map(r=>r.map(cell).join(',')).join('\\r\\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=c.id+'-synthetic.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};\n    c.controls.forEach(a=>document.getElementById(a.id).value=a.value);render();\n  }\n  g.CaseUI={mount,f,plot};\n})(window);\n"}]};
  // Local uploads take precedence. Keep the original importer and its package contract.
  var sc = global.ATLAS.index.byScene[pack.manifest.sceneId];
  var existing = global.Cases.get(pack.manifest.id);
  if (existing) {
    if (sc && existing.tabs && existing.tabs.demo) sc.demo = true;
    return;
  }
  if (global.CaseImport.blockedList().indexOf(pack.manifest.id) >= 0) return;
  var c = pack.manifest;
  var cfg = c.tabs.demo;
  var handle = null;
  c.status = 'ready';
  c.tabs.demo = {
    label: cfg.label, intro: cfg.intro,
    mount: function (root, ctx) {
      handle = global.CaseDemoHost.create(root, { files: pack.files, demo: cfg, meta: c }, ctx);
    },
    unmount: function () { if (handle) { handle.destroy(); handle = null; } }
  };
  global.Cases.register(c);
  if (sc) sc.demo = true;
})(window);
